import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,viewFor,type GameCommand,type GameState} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const amuletPhysicalScenarios=['amulet-lester','amulet-dia','amulet-fear','amulet-decline','amulet-canceled','amulet-refill','amulet-card-charm','amulet-other-ability','amulet-past-stop','amulet-past-charm','amulet-later'] as const;
export type AmuletPhysicalScenario=typeof amuletPhysicalScenarios[number];
export function isAmuletPhysicalScenario(name:string):name is AmuletPhysicalScenario{return (amuletPhysicalScenarios as readonly string[]).includes(name);}
export function amuletMode(name:AmuletPhysicalScenario){const lester=name==='amulet-lester',fear=name==='amulet-fear'||name==='amulet-past-stop',other=name==='amulet-other-ability';return{lester,fear,other,prior:name==='amulet-past-stop'||name==='amulet-past-charm',abilityId:other?'c2-p04-r2c2-ab01':lester?'c2-p03-r2c1-ab01':fear?'c2-p06-r1c1-ab01':'c2-p06-r1c2-ab01',label:other?'影分身':lester?'魔詩':fear?'恐怖':'魅了'};}
/** Initial deal/training; optional old status/allegiance is produced by an actual earlier mental defense. */
export function makeAmuletPhysicalScenario(name:AmuletPhysicalScenario,players:{id:string;name:string}[]){
 const m=amuletMode(name);let s=createGame(players,entropy(),{startingSeat:m.prior?2:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.lester||name==='amulet-card-charm'?'黒騎士ガーウィン':'小人のランバ',m.other?'忍びのイダ':m.lester?'吟遊詩人のレスター':m.fear?'不死王ガドューラ':'魔聖母ディア','有翼人のティア','侍大将のシン'][i]!);for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};
 if(name==='amulet-card-charm')s.players[c]!.permanent!.spirit=20+6-gameStats(s,c).spirit;
 const keep=[takeCard(s,a,'a2-p24-r1c2'),takeCard(s,a,'a2-p24-r2c2'),takeCard(s,a,'a2-p04-r1c2'),takeCard(s,c,'a2-p02-r2c3'),takeCard(s,c,'a2-p14-r1c2'),takeCard(s,d,'a2-p01-r3c2')];for(const p of players)trimHand(s,p.id,...keep);
 let blood:string|undefined;if(name==='amulet-refill'){blood=takeCard(s,a,'a2-p01-r1c3');s.players[a]!.hand=s.players[a]!.hand.filter(id=>id!==blood);}const ordinary=s.deck.filter(id=>getAction(id)!.category!=='open'),opens=s.deck.filter(id=>getAction(id)!.category==='open'),prefix=players.reduce((n,p)=>n+Math.max(0,5-s.players[p.id]!.hand.length),0);s.deck=blood?[...ordinary.slice(0,prefix),blood,...ordinary.slice(prefix),...opens]:[...ordinary,...opens];
 function act(actorId:string,command:GameCommand,dice=Array(100).fill(1)){const input={actorId,command},e={...entropy(),dice},r=transition(s,input,e);if(!r.ok)throw Error(`AMULET_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('AMULET_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('AMULET_FIXTURE_CARDS');}
 function until(done:(s:GameState)=>boolean,dice:number[]){for(let n=0;n<300;n++){if(done(s))return;const w=s.windows?.at(-1);if(!w)throw Error('AMULET_FIXTURE_WINDOW');act(w.participants[w.cursor]!,{type:'PASS'},dice);}throw Error('AMULET_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d])act(id,{type:'PASS_SETUP'});const first=m.prior?c:a;act(first,{type:'START_TURN'});act(first,{type:'CHOOSE_DRAW',draw:false});
 if(m.prior){act(c,{type:'ATTACK',cardInstanceId:'a2-p14-r1c2',targetIds:[b],dedicated:false});until(s=>s.windows?.at(-1)?.kind==='normal-defense',[2,2]);const o=viewFor(s,b).abilityOptions.find(o=>o.abilityId===m.abilityId)!;if(!o)throw Error('AMULET_PRIOR_OPTION');act(b,{type:'USE_ABILITY',abilityId:o.abilityId,targetEventId:o.targetEventId});until(s=>!s.windows?.length,name==='amulet-past-charm'?[6,6]:[2,2]);if(!s.players[c]!.statuses?.some(t=>t.kind==='stopped'))throw Error('AMULET_PRIOR_STOP');if(name==='amulet-past-charm'&&s.players[c]!.faction!=='EVIL')throw Error('AMULET_PRIOR_CHARM');
  for(let n=0;n<100;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===a)break;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(id=>!keep.includes(id)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('AMULET_FIXTURE_PHASE');}
 }
 if(name==='amulet-card-charm'){act(c,{type:'REVEAL_CHARACTER'});until(s=>!s.windows?.length,[1,2]);}if(s.phase!=='action'||s.seatOrder[s.turnSeat]!==a)throw Error('AMULET_FIXTURE_TURN');if(blood&&s.deck[0]!==blood)throw Error('AMULET_REFILL_PREFIX');return s;
}
